insert into public.disputes (id, project_id, milestone_id, evidence_id, kind, submitter_id, submitter_name, submitter_kind, claim, source_url, state, resolution, resolved_by_id, resolved_at, created_at) values
  ('dsp_nimbus_simulation', 'proj_nimbus_wallet', 'ms_nimbus_wallet_tx_simulation', 'ev_nimbus_wallet_tx_simulation_1', 'dispute', '00000000-0000-4000-8000-143423800000', 'Aiko Tanaka', 'community', 'The announcement describes simulation as rolling out, but the feature is only visible to users enrolled in the beta programme. The commitment says all users. Please review before counting this as shipped.', 'https://nimbuswallet.example/docs/beta-features', 'open', null, null, null, '2026-08-02T12:00:00.000Z'),
  ('dsp_hollowmere_marketplace', 'proj_hollowmere_realms', 'ms_hollowmere_realms_marketplace', null, 'correction', '00000000-0000-4000-8000-a7a50f100000', 'Hollowmere Realms team (fictional project representative)', 'project', 'We published a marketplace preview build to founder pass holders. We request the status be changed from no evidence to partially shipped. Conflict of interest: we are the project team.', 'https://hollowmere.example/blog/marketplace-preview', 'under_review', null, null, null, '2026-08-30T12:00:00.000Z'),
  ('dsp_bridgeforge_council', 'proj_bridgeforge', 'ms_bridgeforge_security_council', null, 'dispute', '00000000-0000-4000-8000-f87aa6ea0000', 'Tomasz Rivera', 'community', 'The council was announced but the member list and powers were not public at the time of the shipped status.', null, 'resolved', 'Project published the charter and member list. Status restored to shipped with the publication date as evidence; the prior dispute remains in the audit history.', '00000000-0000-4000-8000-44b1f09d0000', '2026-06-05T12:00:00.000Z', '2026-05-29T12:00:00.000Z')
